PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
BEGIN IMMEDIATE;
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE tasks(task_id TEXT PRIMARY KEY, revision INTEGER NOT NULL CHECK(revision>=0), row_version INTEGER NOT NULL CHECK(row_version>=0), state TEXT NOT NULL CHECK(state IN ('NEW','CLASSIFIED','PLANNED','ASSIGNED','EXECUTING','REVIEWING','VERIFYING','COMPLETION_AUDITING','REREVIEW','REPAIR','ACCEPTED','DONE','BLOCKED','NEEDS_HUMAN_APPROVAL','CANCELLED')), owner TEXT NOT NULL, repository_id TEXT NOT NULL, task_json TEXT NOT NULL CHECK(json_valid(task_json)), updated_at TEXT NOT NULL);
CREATE TABLE events(event_seq INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL UNIQUE, idempotency_key TEXT NOT NULL UNIQUE, task_id TEXT NOT NULL REFERENCES tasks(task_id), revision INTEGER NOT NULL, row_version INTEGER NOT NULL, event_type TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), created_at TEXT NOT NULL);
CREATE TABLE resource_fences(repository_id TEXT PRIMARY KEY, token INTEGER NOT NULL CHECK(token>0));
CREATE TABLE leases(lease_id TEXT PRIMARY KEY, repository_id TEXT NOT NULL, task_id TEXT NOT NULL REFERENCES tasks(task_id), task_revision INTEGER NOT NULL, worker_session_id TEXT NOT NULL, workspace_id TEXT NOT NULL, fencing_token INTEGER NOT NULL CHECK(fencing_token>0), expires_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('ACTIVE','EXPIRED','REVOKED','SUSPECT')));
CREATE TABLE lease_claims(lease_id TEXT NOT NULL REFERENCES leases(lease_id), kind TEXT NOT NULL CHECK(kind IN ('path','logical')), resource_key TEXT NOT NULL, PRIMARY KEY(lease_id,kind,resource_key));
CREATE INDEX idx_lease_status ON leases(repository_id,status,expires_at);
CREATE INDEX idx_claim ON lease_claims(kind,resource_key);
CREATE TABLE evidence(evidence_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(task_id), task_revision INTEGER NOT NULL, commit_sha TEXT NOT NULL, artifact_digest TEXT NOT NULL, attestation_ref TEXT NOT NULL, record_json TEXT NOT NULL CHECK(json_valid(record_json)));
CREATE TABLE approvals(approval_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(task_id), task_revision INTEGER NOT NULL, action_digest TEXT NOT NULL, nonce TEXT NOT NULL UNIQUE, issuer_id TEXT NOT NULL, attestation_ref TEXT NOT NULL, expires_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('APPROVED','DENIED','REVOKED')), record_json TEXT NOT NULL CHECK(json_valid(record_json)));
CREATE TABLE outbox(effect_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(task_id), task_revision INTEGER NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, action_digest TEXT NOT NULL, approval_id TEXT REFERENCES approvals(approval_id), state TEXT NOT NULL CHECK(state IN ('PENDING','DISPATCHING','SUCCEEDED','FAILED','UNKNOWN')), row_version INTEGER NOT NULL DEFAULT 0, provider_operation_id TEXT, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE checkpoints(task_id TEXT PRIMARY KEY REFERENCES tasks(task_id), revision INTEGER NOT NULL, row_version INTEGER NOT NULL, last_event_seq INTEGER NOT NULL REFERENCES events(event_seq), checkpoint_json TEXT NOT NULL CHECK(json_valid(checkpoint_json)));
CREATE TABLE provider_attempts(idempotency_key TEXT PRIMARY KEY, task_id TEXT REFERENCES tasks(task_id), user_turn_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('PREFLIGHT','COMPLETION')), state TEXT NOT NULL CHECK(state IN ('RESERVED','SENT','RESULT','UNAVAILABLE','UNKNOWN')), result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json)), created_at TEXT NOT NULL);
CREATE TABLE budgets(budget_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(task_id), revision INTEGER NOT NULL, row_version INTEGER NOT NULL DEFAULT 0, reserved_tokens INTEGER NOT NULL DEFAULT 0 CHECK(reserved_tokens>=0), used_tokens INTEGER NOT NULL DEFAULT 0 CHECK(used_tokens>=0), reserved_cost REAL NOT NULL DEFAULT 0 CHECK(reserved_cost>=0), used_cost REAL, budget_json TEXT NOT NULL CHECK(json_valid(budget_json)));
CREATE TABLE gate_decisions(decision_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(task_id), task_revision INTEGER NOT NULL, row_version INTEGER NOT NULL, input_digest TEXT NOT NULL, policy_version TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('PASS','FAIL','INCOMPLETE','BLOCKED','NEEDS_HUMAN_APPROVAL')), decision_json TEXT NOT NULL CHECK(json_valid(decision_json)));
INSERT INTO schema_migrations VALUES(1,strftime('%Y-%m-%dT%H:%M:%SZ','now'));
COMMIT;
